// writing-evidence.mjs — Research: numerics & results, formal proof and literature at the point
// of writing (M5 C9).
// Ownership: /research/state view=summary (the owner serves it from its witness-stamp cache:
//   repeated reads are served without re-deriving until an index file changes), /research/
//   result, /research/artifact (paged text and tables), /formal/*, /visuals/state, literature
//   (workspace-literature.mjs). Cards are drawn by research-card.mjs.
// Presentation: result index rows carry the title, a currentness STATE CHIP (owner word), the
//   preview line and the claim summary; the detail card header carries kind, title and the
//   same chip; actions Inspect, Discuss, Connect to claim, Place; Insert citation is the only
//   literature write.
// Public contract: mountWritingEvidence(host,{project,request,pending (the shell's V9 pending-read helper),...});
//   boundedResearchText;
//   researchIndexSummary; delimitedPreview; formalCollectionRows; savedEvidenceView;
//   rememberEvidenceView.
// Storage: sessionStorage laplace:evidence-view:<project>:<view> (index scroll, filter,
//   selected result).
import {inspectArtifactDialog as openEvidenceArtifact} from '/shared/writing-artifact.mjs';
import {openPdf} from '/shared/writing-pdf.mjs';
import {ensureResearchCardStyles,renderResearchCard,renderVisualReadiness,visualRepairPrompt,visualPlacementReason} from '/shared/research-card.mjs';
import {displayLabel,formalAssumptionPosture,formalTargetIndex,scientificText,statementDisplayTex} from '/shared/concept-reader.mjs';
// wave 13 id sweep: control ids by tag and label (begin)
import {declareControl} from '/shared/workspace-presentation.mjs';
// wave 13 id sweep: control ids (end)
// Evidence is useful at the point of writing: inspect it, act on it, cite it.
const el = (tag, text, cls='') => { const n=document.createElement(tag);n.textContent=text||'';n.className=cls;return n; };
function button(label, action) {const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await action();}finally{b.disabled=false;}};return b;}
function section(host,title,help){const s=el('section','','evidence-section');s.append(el('h3',title),el('p',help,'writing-muted'));host.append(s);return s;}
function card(host,title,description){const c=el('article','','writing-card');c.append(el('h4',title));if(description)c.append(el('p',description));host.append(c);return c;}
function link(host,label,href){const a=el('a',label);a.href=href;host.append(a);}
const researchViews=new Map();
const formalViews=new Map();
const evidenceMounts=new WeakMap();
const researchClock=()=>globalThis.performance?.now?.()??Date.now();
const short=value=>String(value||'').replace(/\s+/g,' ').trim();
const statusClass=value=>'research-status research-status--'+String(value||'unknown').toLowerCase().replace(/[^a-z0-9]+/g,'-');
export function boundedResearchText(value,limit=170){
  const text=short(value);if(text.length<=limit)return text;const slice=text.slice(0,limit-1),space=slice.lastIndexOf(' ');return (space>limit*.6?slice.slice(0,space):slice)+'…';
}
export function researchIndexSummary(record){
  const title=short(record.title||record.id),question=short(record.question),finding=short(record.summary),same=(a,b)=>a.toLocaleLowerCase()===b.toLocaleLowerCase();
  const preview=finding&&!same(finding,title)&&!same(finding,question)?{label:record.kind==='experiment'?'Purpose':'Finding',text:boundedResearchText(finding)}:question&&!same(question,title)?{label:'Question',text:boundedResearchText(question)}:null;
  const claims=[...new Map((record.usage||[]).filter(use=>use.concept?.id||use.concept?.label).map(use=>[use.concept.id||use.concept.label,displayLabel(use.concept)])).values()];
  const claimSummary=claims.length?`${claims.length} ${claims.length===1?'claim':'claims'} · `+claims.slice(0,2).map(label=>boundedResearchText(label,36)).join(' · ')+(claims.length>2?` · +${claims.length-2}`:''):'No claim links';
  return {title,preview,claimSummary,claimCount:claims.length};
}
// Parse complete CSV/TSV records, including escaped quotes and quoted newlines.
// A text-page boundary never becomes a fabricated complete final record.
export function delimitedPreview(value,delimiter=',',{complete=true,maxRows=100,maxColumns=32}={}){
  const text=String(value||'').replace(/^\uFEFF/,''),records=[];let row=[],cell='',quoted=false,closedQuote=false,touched=false,count=0,width=0;
  const field=()=>{row.push(cell);cell='';closedQuote=false;};
  const record=()=>{field();width=Math.max(width,row.length);count++;if(records.length<=maxRows)records.push(row.slice(0,maxColumns));row=[];touched=false;};
  for(let at=0;at<text.length;at++){
    const char=text[at];touched=true;
    if(quoted){if(char==='"'){if(text[at+1]==='"'){cell+='"';at++;}else{quoted=false;closedQuote=true;}}else cell+=char;continue;}
    if(char==='"'){if(cell||closedQuote)return {error:'Unexpected quote in an unquoted field. Show source to inspect the file.'};quoted=true;continue;}
    if(char===delimiter){field();continue;}
    if(char==='\r'||char==='\n'){if(char==='\r'&&text[at+1]==='\n')at++;record();continue;}
    if(closedQuote){if(/\s/.test(char))continue;return {error:'Unexpected text after a quoted field. Show source to inspect the file.'};}
    cell+=char;
  }
  const partial=touched||row.length>0||cell.length>0||quoted;
  if(complete&&quoted)return {error:'The file ends inside a quoted field. Show source to inspect the incomplete record.'};
  if(complete&&partial)record();
  const headers=records.shift()||[],rows=records;
  return {headers,rows,rowCount:Math.max(0,count-1),complete,partialFinalRow:!complete&&!!partial,rowsOmitted:Math.max(0,count-1-rows.length),columns:width,columnsOmitted:Math.max(0,width-maxColumns)};
}

export function formalCollectionRows(targets,receipts,query=''){
  const needle=short(query).toLocaleLowerCase(),groupNames={definition:'Definitions',postulate:'Assumptions',lemma:'Lemmas',theorem:'Theorems',result:'Results','intermediate-result':'Intermediate results','derivation-step':'Derivations',support:'Supporting claims',technique:'Methods',goal:'Goals'};
  return formalTargetIndex(targets,receipts).map(row=>({...row,title:displayLabel(row.target),group:row.target.concept_kind||'unknown',groupLabel:groupNames[row.target.concept_kind]||'Mathematical targets'})).filter(row=>!needle||[row.target.id,row.title,row.target.label,row.target.statement_tex,row.target.domain,row.target.statement_origin,row.target.origin_posture,row.target.documentation_status,row.target.concept_kind,row.groupLabel,row.status].some(value=>short(value).toLocaleLowerCase().includes(needle)));
}

export function savedEvidenceView(project,view){
  const cache=view==='formal'?formalViews:researchViews,key=project+'::'+view;if(cache.has(key))return cache.get(key);
  let value={};try{value=JSON.parse(globalThis.sessionStorage?.getItem('laplace:evidence-view:'+key)||'{}');}catch{}
  if(!value||typeof value!=='object')value={};
  const state={query:typeof value.query==='string'?value.query:'',selected:typeof value.selected==='string'?value.selected:null,detail:value.detail===true,indexScroll:Number(value.indexScroll)||0,...(Array.isArray(value.matchedIds)?{matchedIds:value.matchedIds}: {})};cache.set(key,state);return state;
}
export function rememberEvidenceView(project,view,state){
  (view==='formal'?formalViews:researchViews).set(project+'::'+view,state);try{globalThis.sessionStorage?.setItem('laplace:evidence-view:'+project+'::'+view,JSON.stringify(state));}catch{}
}

export function focusResearchResult(project,id,view='numerics'){
  const state=savedEvidenceView(project,view);state.query='';state.selected=id;state.detail=true;rememberEvidenceView(project,view,state);return state;
}

